CREATE OR REPLACE FUNCTION public.guard_capital_only_recovery_marker() RETURNS trigger LANGUAGE plpgsql SET search_path = public AS $$ DECLARE v_marker constant text := '[CAPITAL_ONLY_RECOVERY]'; v_notes text; BEGIN v_notes := coalesce(NEW.notes,''); IF (TG_OP = 'INSERT' OR NEW.capital_only_recovery IS NOT DISTINCT FROM OLD.capital_only_recovery) AND coalesce(NEW.capital_only_recovery,false) = false AND position(v_marker in v_notes) > 0 THEN NEW.capital_only_recovery := true; END IF; IF coalesce(NEW.capital_only_recovery,false) THEN IF position(v_marker in v_notes) = 0 THEN NEW.notes := concat_ws(E'\n', nullif(btrim(v_notes),''), v_marker || ' Somente capital: recuperar apenas o principal, sem juros ou encargos.'); END IF; ELSE SELECT coalesce(string_agg(line,E'\n' ORDER BY ord),'') INTO v_notes FROM unnest(string_to_array(v_notes,E'\n')) WITH ORDINALITY AS x(line,ord) WHERE position(v_marker in line)=0; NEW.notes := nullif(btrim(v_notes),''); END IF; RETURN NEW; END; $$; DROP TRIGGER IF EXISTS trg_guard_capital_only_recovery_marker ON public.contratos; CREATE TRIGGER trg_guard_capital_only_recovery_marker BEFORE INSERT OR UPDATE OF notes, capital_only_recovery ON public.contratos FOR EACH ROW EXECUTE FUNCTION public.guard_capital_only_recovery_marker();;
